import { model, Schema } from 'mongoose';
import { EVENT_TYPES } from '@riad/shared';

/** How long raw events are kept. Proposed default: 90 days. */
export const EVENT_RETENTION_DAYS = 90;

const eventSchema = new Schema({
  /** Generated by the browser; lets retried batches be accepted without double counting. */
  eventId: { type: String, required: true, unique: true },
  type: { type: String, enum: EVENT_TYPES, required: true },
  visitorId: { type: String, required: true },
  sessionId: { type: String, required: true },
  path: { type: String, required: true },
  productId: { type: Schema.Types.ObjectId },
  durationMs: { type: Number },
  label: { type: String },
  value: { type: Number },
  at: { type: Date, required: true },
  receivedAt: { type: Date, default: Date.now },
  policyVersion: { type: String },
  /** Source and device, stored once per batch on its first event. */
  ctx: { type: Schema.Types.Mixed },
  expiresAt: { type: Date, required: true },
});

eventSchema.index({ visitorId: 1, at: -1 });
eventSchema.index({ sessionId: 1, at: 1 });
eventSchema.index({ type: 1, at: -1 });
eventSchema.index({ productId: 1, type: 1, at: -1 });
// MongoDB deletes each event when it expires. Reads also ignore expired rows.
eventSchema.index({ expiresAt: 1 }, { expireAfterSeconds: 0 });

export const TrackingEvent = model('TrackingEvent', eventSchema);
